1	"use client";
2	
3	import { useMutation, useQuery } from "convex/react";
4	import { ArrowLeft, MapPin, Star } from "lucide-react";
5	import { useRouter, useSearchParams } from "next/navigation";
6	import { use, useEffect, useRef, useState } from "react";
7	import { toast } from "sonner";
8	import { ItemActivityTimeline } from "@/components/item-activity-timeline";
9	import { BorrowerRequestPanel } from "@/components/lease/borrower-request-panel";
10	import { LeaseClaimCard } from "@/components/lease/lease-claim-card";
11	import { ItemForm } from "@/components/item-form";
12	import { RatingForm } from "@/components/rating-form";
13	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
14	import {
15	  AlertDialog,
16	  AlertDialogAction,
17	  AlertDialogCancel,
18	  AlertDialogContent,
19	  AlertDialogDescription,
20	  AlertDialogFooter,
21	  AlertDialogHeader,
22	  AlertDialogTitle,
23	  AlertDialogTrigger,
24	} from "@/components/ui/alert-dialog";
25	import {
26	  Dialog,
27	  DialogContent,
28	  DialogHeader,
29	  DialogTitle,
30	} from "@/components/ui/dialog";
31	import { Badge } from "@/components/ui/badge";
32	import { Button } from "@/components/ui/button";
33	import { ItemImageCarousel } from "@/components/item-image-carousel";
34	import { Toggle } from "@/components/ui/toggle";
35	import { ItemCalendar } from "@/components/item-calendar";
36	import { isCloudinaryImageUrl } from "@/components/cloudinary-image";
37	import { cn } from "@/lib/utils";
38	import { useItemCalendar } from "@/hooks/use-item-calendar";
39	import { useTrackedPickup } from "@/hooks/use-tracked-pickup";
40	import { api } from "@/convex/_generated/api";
41	import type { Doc, Id } from "@/convex/_generated/dataModel";
42	import { useTranslations } from "next-intl";
43	
44	export default function ItemDetailPage({
45	  params,
46	}: {
47	  params: Promise<{ id: Id<"items"> }>;
48	}) {
49	  const { id } = use(params);
50	  const router = useRouter();
51	  const searchParams = useSearchParams();
52	  const tCategories = useTranslations("Categories");
53	  const tDetail = useTranslations("ItemDetail");
54	  const tCommon = useTranslations("Common");
55	
56	  const item = useQuery(api.items.getById, { id });
57	  const activity = useQuery(api.items.getItemActivity, { itemId: id });
58	  const pendingRatings = useQuery(api.ratings.getMyPendingRatings);
59	
60	  // Mutations for Owner
61	  const updateItem = useMutation(api.items.update);
62	  const switchItemMode = useMutation(api.items.switchItemMode);
63	  const deleteItem = useMutation(api.items.deleteItem);
64	  const approveClaim = useMutation(api.items.approveClaim);
65	  const rejectClaim = useMutation(api.items.rejectClaim);
66	  const markPickedUp = useTrackedPickup();
67	  const markReturned = useMutation(api.items.markReturned);
68	  const markExpired = useMutation(api.items.markExpired);
69	  const markMissing = useMutation(api.items.markMissing);
70	
71	  // UI State
72	  const [isEditing, setIsEditing] = useState(false);
73	  const [showInactive, setShowInactive] = useState(false);
74	  const [selectedRatingClaim, setSelectedRatingClaim] = useState<{
75	    claimId: Id<"claims">;
76	    targetRole: "lender" | "borrower";
77	    itemName: string;
78	  } | null>(null);
79	  const claimCardRefs = useRef<Map<Id<"claims">, HTMLDivElement>>(new Map());
80	
81	  const focusClaimCard = (claimId: Id<"claims">) => {
82	    const el = claimCardRefs.current.get(claimId);
83	    if (!el) return;
84	    el.scrollIntoView({ block: "nearest", behavior: "smooth" });
85	    el.focus();
86	  };
87	
88	  // Auto-open rating dialog if rateClaimId is in URL params
89	  useEffect(() => {
90	    const rateClaimId = searchParams.get("rateClaimId");
91	    const targetRoleParam = searchParams.get("targetRole");
92	    const targetRole: "lender" | "borrower" | null =
93	      targetRoleParam === "lender" || targetRoleParam === "borrower"
94	        ? targetRoleParam
95	        : null;
96	
97	    if (rateClaimId && targetRole && pendingRatings && item) {
98	      const pendingRating = pendingRatings.find(
99	        (p) => p.claimId === rateClaimId && p.targetRole === targetRole,
100	      );
101	
102	      if (pendingRating && !selectedRatingClaim) {
103	        setSelectedRatingClaim({
104	          claimId: rateClaimId as Id<"claims">,
105	          targetRole,
106	          itemName: pendingRating.itemName,
107	        });
108	        // Clean up URL params
109	        const newUrl = new URL(window.location.href);
110	        newUrl.searchParams.delete("rateClaimId");
111	        newUrl.searchParams.delete("targetRole");
112	        router.replace(newUrl.pathname + newUrl.search, { scroll: false });
113	      }
114	    }
115	  }, [searchParams, pendingRatings, item, selectedRatingClaim, router]);
116	
117	  const ownerRequests = ((item?.requests ?? []) as Doc<"claims">[]) ?? [];
118	  const ownerCalendarState = useItemCalendar({
119	    mode: "owner",
120	    itemId: id,
121	    requests: ownerRequests,
122	    months: 2,
123	    onFocusClaim: focusClaimCard,
124	  });
125	
126	  const requestsToShow = ownerRequests.filter((req) => {
127	    if (showInactive) return true;
128	    // Active means:
129	    // 1. Pending
130	    // 2. Approved AND NOT (returned OR transferred OR expired OR missing)
131	    if (req.status === "pending") return true;
132	    if (req.status === "approved") {
133	      return (
134	        !req.returnedAt &&
135	        !req.transferredAt &&
136	        !req.expiredAt &&
137	        !req.missingAt
138	      );
139	    }
140	    return false;
141	  });
142	
143	  const approveClaimAction = async (
144	    args: Parameters<typeof approveClaim>[0],
145	  ) => {
146	    await approveClaim(args);
147	  };
148	  const rejectClaimAction = async (args: Parameters<typeof rejectClaim>[0]) => {
149	    await rejectClaim(args);
150	  };
151	  const markPickedUpAction = async (
152	    args: Parameters<typeof markPickedUp>[0],
153	  ) => {
154	    await markPickedUp(args);
155	  };
156	  const markReturnedAction = async (
157	    args: Parameters<typeof markReturned>[0],
158	  ) => {
159	    await markReturned(args);
160	  };
161	  const markExpiredAction = async (args: Parameters<typeof markExpired>[0]) => {
162	    await markExpired(args);
163	  };
164	  const markMissingAction = async (args: Parameters<typeof markMissing>[0]) => {
165	    await markMissing(args);
166	  };
167	
168	  if (item === undefined) {
169	    return <div className="p-8 text-center">{tCommon("loading")}</div>;
170	  }
171	
172	  if (item === null) {
173	    return <div className="p-8 text-center">{tDetail("notFound")}</div>;
174	  }
175	
176	  const imageUrls = (item.imageUrls ?? []).filter(isCloudinaryImageUrl);
177	
178	  const pendingRatingsForItem =
179	    pendingRatings?.filter((pending) => pending.itemId === id) ?? [];
180	
181	  const getRatingPrompt = (
182	    isGiveaway: boolean,
183	    targetRole: "lender" | "borrower",
184	    targetUserName: string | null,
185	  ): string => {
186	    if (isGiveaway) {
187	      if (targetUserName) {
188	        return targetRole === "lender"
189	          ? tDetail("ratePrompt.receiveFromUser", { targetUserName })
190	          : tDetail("ratePrompt.giveToUser", { targetUserName });
191	      }
192	      return targetRole === "lender"
193	        ? tDetail("ratePrompt.receive")
194	        : tDetail("ratePrompt.give");
195	    }
196	    if (targetUserName) {
197	      return targetRole === "lender"
198	        ? tDetail("ratePrompt.borrowFromUser", { targetUserName })
199	        : tDetail("ratePrompt.lendToUser", { targetUserName });
200	    }
201	    return targetRole === "lender"
202	      ? tDetail("ratePrompt.borrow")
203	      : tDetail("ratePrompt.lend");
204	  };
205	
206	  const rateTransactionSection =
207	    pendingRatingsForItem.length > 0 && !selectedRatingClaim ? (
208	      <Card className="border-yellow-200 bg-yellow-50/60">
209	        <CardContent className="py-3 px-4 space-y-3">
210	          <div className="flex items-center gap-2">
211	            <Star className="h-4 w-4 text-yellow-500" />
212	            <p className="text-sm font-medium">
213	              {tDetail("rate")}{" "}
214	              {pendingRatingsForItem.length > 1
215	                ? tDetail("rateTransactions")
216	                : tDetail("rateTransaction")}
217	            </p>
218	          </div>
219	          <div className="space-y-2">
220	            {pendingRatingsForItem.map((pending) => {
221	              const ratingPrompt = getRatingPrompt(
222	                item.giveaway ?? false,
223	                pending.targetRole,
224	                pending.targetUserName,
225	              );
226	              return (
227	                <div
228	                  key={pending.claimId}
229	                  className="flex items-center justify-between gap-3 p-2 bg-white rounded-md border"
230	                >
231	                  <div className="min-w-0">
232	                    <p className="text-xs font-medium">
233	                      {tDetail("reviewTransaction")}
234	                    </p>
235	                    <p className="text-xs text-muted-foreground">
236	                      {ratingPrompt}
237	                    </p>
238	                  </div>
239	                  <Button
240	                    size="sm"
241	                    variant="outline"
242	                    onClick={() =>
243	                      setSelectedRatingClaim({
244	                        claimId: pending.claimId as Id<"claims">,
245	                        targetRole: pending.targetRole,
246	                        itemName: pending.itemName,
247	                      })
248	                    }
249	                  >
250	                    {tDetail("rate")}
251	                  </Button>
252	                </div>
253	              );
254	            })}
255	          </div>
256	        </CardContent>
257	      </Card>
258	    ) : null;
259	
260	  const ownerCalendar = item.isOwner ? (
261	    <div className="bg-white border rounded-lg p-4 w-full">
262	      <div className="flex justify-center w-full max-w-full">
263	        <ItemCalendar {...ownerCalendarState.calendarProps} />
264	      </div>
265	    </div>
266	  ) : null;
267	
268	  const imageSection =
269	    imageUrls.length > 0 ? (
270	      <ItemImageCarousel
271	        imageUrls={imageUrls}
272	        name={item.name}
273	        aspectRatio="4/3"
274	        sizes="(max-width: 1024px) 100vw, 560px"
275	      />
276	    ) : null;
277	
278	  const detailsSection = (
279	    <div>
280	      <div className="flex justify-between items-start">
281	        <h1 className="text-xl md:text-2xl font-bold mb-2">{item.name}</h1>
282	        {item.isOwner && (
283	          <Badge variant="outline">{tDetail("youOwnThis")}</Badge>
284	        )}
285	      </div>
286	
287	      <div className="flex flex-wrap gap-2 mb-4">
288	        {item.giveaway ? (
289	          <Badge>{tDetail("giveaway")}</Badge>
290	        ) : (
291	          <Badge variant="outline">{tDetail("loan")}</Badge>
292	        )}
293	        {item.category && (
294	          <Badge variant="secondary">{tCategories(item.category)}</Badge>
295	        )}
296	        {item.location && (
297	          <span className="inline-flex items-center gap-1 text-sm text-muted-foreground">
298	            <MapPin className="h-4 w-4" />
299	            {item.isOwner
300	              ? item.location.address ||
301	                `${item.location.lat.toFixed(4)}, ${item.location.lng.toFixed(4)}`
302	              : item.location.ward || tDetail("locationAvailable")}
303	          </span>
304	        )}
305	      </div>
306	      <p className="text-sm md:text-base text-muted-foreground leading-relaxed">
307	        {item.description}
308	      </p>
309	    </div>
310	  );
311	
312	  const ownerItemActions = item.isOwner ? (
313	    <div className="flex flex-wrap gap-4">
314	      <Button variant="outline" onClick={() => setIsEditing((v) => !v)}>
315	        {isEditing ? tDetail("cancel") : tDetail("editItem")}
316	      </Button>
317	
318	      <AlertDialog>
319	        <AlertDialogTrigger asChild>
320	          <Button variant="destructive">{tDetail("deleteItem")}</Button>
321	        </AlertDialogTrigger>
322	        <AlertDialogContent>
323	          <AlertDialogHeader>
324	            <AlertDialogTitle>
325	              {tDetail("deleteConfirm.title")}
326	            </AlertDialogTitle>
327	            <AlertDialogDescription>
328	              {tDetail("deleteConfirm.description")}
329	            </AlertDialogDescription>
330	          </AlertDialogHeader>
331	          <AlertDialogFooter>
332	            <AlertDialogCancel>{tDetail("cancel")}</AlertDialogCancel>
333	            <AlertDialogAction
334	              onClick={async () => {
335	                await deleteItem({ id: item._id });
336	                toast.success(tDetail("itemDeleted"));
337	                router.push("/");
338	              }}
339	            >
340	              {tDetail("deleteConfirm.confirm")}
341	            </AlertDialogAction>
342	          </AlertDialogFooter>
343	        </AlertDialogContent>
344	      </AlertDialog>
345	    </div>
346	  ) : null;
347	
348	  const viewSection = (
349	    <div
350	      data-state={isEditing ? "closed" : "open"}
351	      className={cn(
352	        "grid overflow-hidden transition-[grid-template-rows] duration-300 ease-out",
353	        "data-[state=open]:grid-rows-[1fr] data-[state=closed]:grid-rows-[0fr]",
