359	          {imageSection}
360	        </div>
361	      </div>
362	    </div>
363	  );
364	
365	  const editSection = (
366	    <div
367	      data-state={isEditing ? "open" : "closed"}
368	      className={cn(
369	        "grid overflow-hidden transition-[grid-template-rows] duration-300 ease-out",
370	        "data-[state=open]:grid-rows-[1fr] data-[state=closed]:grid-rows-[0fr]",
371	      )}
372	    >
373	      <div className="min-h-0 overflow-hidden">
374	        <div className="data-[state=open]:animate-in data-[state=open]:fade-in data-[state=open]:slide-in-from-top-2">
