380	              <ItemForm
381	                initialValues={{
382	                  name: item.name,
383	                  description: item.description || "",
384	                  images: item.images,
385	                  category: item.category,
386	                  location: item.location,
387	                  giveaway: Boolean(item.giveaway),
388	                  minLeaseDays: item.minLeaseDays,
389	                  maxLeaseDays: item.maxLeaseDays,
390	                }}
391	                enableModeSwitch
392	                onSubmit={async (values) => {
393	                  if (
394	                    typeof values.giveaway === "boolean" &&
395	                    values.giveaway !== Boolean(item.giveaway)
396	                  ) {
397	                    await switchItemMode({
398	                      id: item._id,
399	                      giveaway: values.giveaway,
400	                    });
401	                  }
402	                  await updateItem({
403	                    id: item._id,
404	                    name: values.name,
405	                    description: values.description,
406	                    imageCloudinary: values.imageCloudinary,
407	                    category: values.category,
408	                    location: values.location,
409	                    minLeaseDays: values.minLeaseDays,
410	                    maxLeaseDays: values.maxLeaseDays,
411	                  });
412	                  setIsEditing(false);
413	                  toast.success(tDetail("itemUpdated"));
414	                }}
415	                submitLabel={tDetail("saveChanges")}
416	                hideMyItemsLink
417	                footerActions={
418	                  <Button variant="outline" onClick={() => setIsEditing(false)}>
419	                    {tDetail("cancel")}
420	                  </Button>
421	                }
422	              />
423	            </CardContent>
424	          </Card>
425	        </div>
426	      </div>
427	    </div>
428	  );
429	
430	  const leftColumn = (
431	    <>
432	      <div className="space-y-6">
433	        {viewSection}
434	        {rateTransactionSection}
435	        {!isEditing ? ownerItemActions : null}
436	        {editSection}
437	      </div>
438	      <Dialog
439	        open={selectedRatingClaim !== null}
440	        onOpenChange={() => setSelectedRatingClaim(null)}
441	      >
442	        <DialogContent>
443	          <DialogHeader>
444	            <DialogTitle>{tDetail("leaveRating")}</DialogTitle>
445	          </DialogHeader>
446	          {selectedRatingClaim && (
447	            <RatingForm
448	              claimId={selectedRatingClaim.claimId}
449	              targetRole={selectedRatingClaim.targetRole}
450	              itemName={selectedRatingClaim.itemName}
451	              onSuccess={() => setSelectedRatingClaim(null)}
452	              onCancel={() => setSelectedRatingClaim(null)}
453	            />
454	          )}
455	        </DialogContent>
456	      </Dialog>
457	    </>
458	  );
459	
460	  const ownerActionsSection = (
461	    <div className="space-y-6">
462	      <div>
463	        <div className="flex justify-between items-center mb-4">
464	          <h3 className="text-base font-semibold">
