9	
10	type ResolvedUser = {
11	  email: string;
12	  name: string;
13	  profile: Doc<"users">;
14	};
15	
16	async function resolveUserEmail(
17	  ctx: MutationCtx,
18	  clerkId: string,
19	  context: string,
20	): Promise<ResolvedUser | null> {
21	  const profile = await ctx.db
22	    .query("users")
23	    .withIndex("by_clerk_id", (q) => q.eq("clerkId", clerkId))
24	    .first();
25	
26	  if (!profile?.email) {
27	    console.warn(
28	      `[email skip] ${context}: user ${clerkId} has no email on file. ` +
29	        "Run users:backfillEmailsFromClerk or set up the Clerk webhook.",
30	    );
31	    return null;
32	  }
33	
34	  return { email: profile.email, name: profile.name ?? "there", profile };
