"use client";

import { useQuery } from "convex/react";
import { MessageSquare } from "lucide-react";
import { useTranslations } from "next-intl";

import { Link } from "@/i18n/routing";
import { api } from "@/convex/_generated/api";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";

function formatRelative(timestamp: number, locale: string): string {
  if (!timestamp) return "";
  try {
    return new Intl.DateTimeFormat(locale, {
      month: "short",
      day: "numeric",
      hour: "numeric",
      minute: "2-digit",
    }).format(new Date(timestamp));
  } catch {
    return new Date(timestamp).toLocaleString();
  }
}

export function ConversationsList() {
  const t = useTranslations("Messages");
  const conversations = useQuery(api.messaging.listMyConversations);
  const localeStrings = useTranslations("Locale");
  const localeTag = (() => {
    try {
      return localeStrings("tag");
    } catch {
      return "en-US";
    }
  })();

  if (conversations === undefined) {
    return (
      <div className="text-center py-10 text-muted-foreground">
        {t("loading")}
      </div>
    );
  }

  if (conversations.length === 0) {
    return (
      <div className="space-y-3">
        <h1 className="text-xl md:text-2xl font-bold">{t("title")}</h1>
        <Card className="p-8 text-center text-sm text-muted-foreground">
          {t("empty")}
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      <h1 className="text-xl md:text-2xl font-bold">{t("title")}</h1>
      <ul className="divide-y rounded-lg border bg-white">
        {conversations.map((c) => (
          <li key={c._id}>
            <Link
              href={{ pathname: "/messages/[id]", params: { id: c._id } }}
              className="flex items-start gap-3 p-3 hover:bg-gray-50 transition-colors"
            >
              <div className="flex-shrink-0 h-12 w-12 rounded-md bg-muted overflow-hidden">
                {c.itemImageUrl ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img
                    src={c.itemImageUrl}
                    alt={c.itemName}
                    className="h-full w-full object-cover"
                  />
                ) : (
                  <div className="h-full w-full flex items-center justify-center text-muted-foreground">
                    <MessageSquare className="h-5 w-5" />
                  </div>
                )}
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between gap-2">
                  <p
                    className={cn(
                      "text-sm truncate",
                      c.unreadCount > 0 ? "font-semibold" : "font-medium",
                    )}
                  >
                    {c.otherUserName ?? t("unknownUser")}
                  </p>
                  <span className="text-[11px] text-muted-foreground flex-shrink-0">
                    {formatRelative(c.lastMessageAt, localeTag)}
                  </span>
                </div>
                <p className="text-xs text-muted-foreground truncate">
                  {c.itemName}
                </p>
                <p
                  className={cn(
                    "text-sm truncate mt-0.5",
                    c.unreadCount > 0
                      ? "text-foreground"
                      : "text-muted-foreground",
                  )}
                >
                  {c.lastMessagePreview ?? t("noMessages")}
                </p>
              </div>
              {c.unreadCount > 0 && (
                <span className="ml-2 inline-flex items-center justify-center min-w-5 h-5 px-1.5 rounded-full bg-primary text-primary-foreground text-[11px] font-semibold">
                  {c.unreadCount > 99 ? "99+" : c.unreadCount}
                </span>
              )}
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}

