"use client";

import { useMutation, useQuery } from "convex/react";
import { ArrowLeft, Send } from "lucide-react";
import { useLocale, useTranslations } from "next-intl";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useAuth } from "@clerk/nextjs";
import { toast } from "sonner";

import { Link } from "@/i18n/routing";
import { api } from "@/convex/_generated/api";
import type { Doc, Id } from "@/convex/_generated/dataModel";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

interface MessageThreadProps {
  conversationId: Id<"conversations">;
}

function formatTime(ts: number, locale: string): string {
  try {
    return new Intl.DateTimeFormat(locale, {
      hour: "numeric",
      minute: "2-digit",
    }).format(new Date(ts));
  } catch {
    return new Date(ts).toLocaleTimeString();
  }
}

function formatDate(ts: number, locale: string): string {
  try {
    return new Intl.DateTimeFormat(locale, {
      month: "short",
      day: "numeric",
      year: "numeric",
    }).format(new Date(ts));
  } catch {
    return new Date(ts).toLocaleDateString();
  }
}

const SYSTEM_TYPE_KEYS: Record<string, string> = {
  lease_requested: "system.requested",
  lease_approved: "system.approved",
  lease_rejected: "system.rejected",
};

function SystemBubble({
  message,
  itemName,
  t,
}: {
  message: Doc<"conversation_messages">;
  itemName: string;
  t: ReturnType<typeof useTranslations>;
}) {
  const key = message.systemType
    ? SYSTEM_TYPE_KEYS[message.systemType]
    : undefined;
  const text = key ? t(key, { item: itemName }) : message.body;
  return (
    <div className="flex justify-center my-2">
      <span className="text-[11px] text-muted-foreground bg-muted/60 px-3 py-1 rounded-full">
        {text}
      </span>
    </div>
  );
}

export function MessageThread({ conversationId }: MessageThreadProps) {
  const t = useTranslations("Messages");
  const localeTag = useLocale();
  const { userId: clerkUserId } = useAuth();

  const conversation = useQuery(api.messaging.getConversation, {
    conversationId,
  });
  const messages = useQuery(api.messaging.listMessages, { conversationId });
  const sendMessage = useMutation(api.messaging.sendMessage);
  const markRead = useMutation(api.messaging.markRead);

  const [draft, setDraft] = useState("");
  const [isSending, setIsSending] = useState(false);
  const bottomRef = useRef<HTMLDivElement | null>(null);
  const lastMarkedRef = useRef<number>(0);

  const lastMessageAt = useMemo(() => {
    if (!messages || messages.length === 0) return 0;
    return messages[messages.length - 1].createdAt;
  }, [messages]);

  useEffect(() => {
    if (!conversation || !messages) return;
    if (lastMessageAt > lastMarkedRef.current) {
      lastMarkedRef.current = lastMessageAt;
      void markRead({ conversationId });
    }
  }, [conversation, messages, lastMessageAt, conversationId, markRead]);

  useEffect(() => {
    if (bottomRef.current) {
      bottomRef.current.scrollIntoView({ block: "end" });
    }
  }, [messages?.length]);

  const handleSend = useCallback(async () => {
    const body = draft.trim();
    if (!body || isSending) return;
    setIsSending(true);
    try {
      await sendMessage({ conversationId, body });
      setDraft("");
    } catch (err) {
      toast.error(err instanceof Error ? err.message : t("sendFailed"));
    } finally {
      setIsSending(false);
    }
  }, [draft, isSending, sendMessage, conversationId, t]);

  if (conversation === undefined || messages === undefined) {
    return (
      <div className="text-center py-10 text-muted-foreground">
        {t("loading")}
      </div>
    );
  }

  if (conversation === null) {
    return (
      <div className="text-center py-10 text-muted-foreground">
        {t("notFound")}
      </div>
    );
  }

  let lastDateLabel: string | null = null;

  return (
    <div className="flex flex-col h-[calc(100dvh-160px)] md:h-[calc(100dvh-180px)]">
      <div className="flex items-center gap-2 pb-2">
        <Link href="/messages">
          <Button variant="ghost" size="sm" className="gap-1">
            <ArrowLeft className="h-4 w-4" />
            {t("back")}
          </Button>
        </Link>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-semibold truncate">
            {conversation.otherUserName ?? t("unknownUser")}
          </p>
          <Link
            href={`/item/${conversation.itemId}`}
            className="text-xs text-muted-foreground truncate hover:underline"
          >
            {conversation.itemName}
          </Link>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto rounded-lg border bg-white p-3 space-y-1">
        {messages.length === 0 ? (
          <p className="text-center text-sm text-muted-foreground py-10">
            {t("threadEmpty")}
          </p>
        ) : (
          messages.map((m) => {
            const dateLabel = formatDate(m.createdAt, localeTag);
            const showDate = dateLabel !== lastDateLabel;
            lastDateLabel = dateLabel;

            if (m.kind === "system") {
              return (
                <div key={m._id}>
                  {showDate && (
                    <div className="text-center text-[11px] text-muted-foreground my-3">
                      {dateLabel}
                    </div>
                  )}
                  <SystemBubble
                    message={m}
                    itemName={conversation.itemName}
                    t={t}
                  />
                </div>
              );
            }

            const isMine = clerkUserId === m.senderId;
            return (
              <div key={m._id}>
                {showDate && (
                  <div className="text-center text-[11px] text-muted-foreground my-3">
                    {dateLabel}
                  </div>
                )}
                <div
                  className={cn(
                    "flex flex-col max-w-[80%]",
                    isMine ? "ml-auto items-end" : "items-start",
                  )}
                >
                  <div
                    className={cn(
                      "rounded-2xl px-3 py-2 text-sm whitespace-pre-wrap break-words",
                      isMine
                        ? "bg-primary text-primary-foreground"
                        : "bg-muted text-foreground",
                    )}
                  >
                    {m.body}
                  </div>
                  <span className="text-[10px] text-muted-foreground mt-0.5">
                    {formatTime(m.createdAt, localeTag)}
                  </span>
                </div>
              </div>
            );
          })
        )}
        <div ref={bottomRef} />
      </div>

      <form
        className="flex items-end gap-2 pt-2"
        onSubmit={(e) => {
          e.preventDefault();
          void handleSend();
        }}
      >
        <Textarea
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              void handleSend();
            }
          }}
          rows={1}
          placeholder={t("placeholder")}
          className="min-h-[40px] max-h-32 resize-none"
          disabled={isSending}
        />
        <Button
          type="submit"
          size="icon"
          disabled={isSending || draft.trim().length === 0}
          aria-label={t("send")}
        >
          <Send className="h-4 w-4" />
        </Button>
      </form>
    </div>
  );
}

