"use client";

import { useMutation } from "convex/react";
import { MessageSquare } from "lucide-react";
import { useTranslations } from "next-intl";
import { useState } from "react";
import { toast } from "sonner";

import { useRouter } from "@/i18n/routing";
import { api } from "@/convex/_generated/api";
import type { Id } from "@/convex/_generated/dataModel";
import { Button } from "@/components/ui/button";

interface MessageOwnerButtonProps {
  itemId: Id<"items">;
  claimId?: Id<"claims">;
  variant?: "default" | "outline" | "ghost";
  size?: "default" | "sm" | "icon";
  className?: string;
  fullWidth?: boolean;
}

export function MessageOwnerButton({
  itemId,
  claimId,
  variant = "outline",
  size = "sm",
  className,
  fullWidth,
}: MessageOwnerButtonProps) {
  const t = useTranslations("Messages");
  const router = useRouter();
  const startConversation = useMutation(api.messaging.startConversation);
  const [isPending, setIsPending] = useState(false);

  const handleClick = async () => {
    if (isPending) return;
    setIsPending(true);
    try {
      const id = await startConversation({ itemId, claimId });
      router.push(`/messages/${id}`);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : t("openFailed"));
    } finally {
      setIsPending(false);
    }
  };

  return (
    <Button
      type="button"
      variant={variant}
      size={size}
      onClick={handleClick}
      disabled={isPending}
      className={`${fullWidth ? "w-full " : ""}gap-1 ${className ?? ""}`.trim()}
    >
      <MessageSquare className="h-4 w-4" />
      {t("messageButton")}
    </Button>
  );
}

