"use client";

import { useMutation, useQuery } from "convex/react";
import {
  Check,
  Clock,
  X,
  AlertTriangle,
  Package,
  PackageCheck,
} from "lucide-react";
import { format } from "date-fns";
import { useMemo, useState } from "react";
import { toast } from "sonner";
import { useTranslations } from "next-intl";

import type { LeaseActivityEvent } from "./lease-activity-timeline";
import { LeaseActionDialog } from "./lease-action-dialog";
import { LeaseClaimHeader } from "./lease-claim-header";
import { LeaseJourneyStepper } from "./lease-journey-stepper";
import { LeaseJourneyTimeline } from "./lease-journey-timeline";
import { getFlowType } from "./lease-journey-utils";
import { LeaseProposeWindowDialog } from "./lease-propose-window-dialog";
import type {
  ApproveClaimArgs,
  CancelClaimArgs,
  MarkLeaseStatusArgs,
  MutationResult,
  RecordLeaseArgs,
  RecordPickupArgs,
  RejectClaimArgs,
  ViewerRole,
} from "./lease-claim-types";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { api } from "@/convex/_generated/api";
import type { Doc, Id } from "@/convex/_generated/dataModel";

function getLeaseState(claim: Doc<"claims">): string {
  if (claim.status === "rejected") return "rejected";
  if (claim.status === "approved") return "approved";
  return "requested";
}

function badgeVariantForState(
  state: string,
): "default" | "secondary" | "outline" | "destructive" {
  switch (state) {
    case "approved":
      return "default";
    case "requested":
      return "secondary";
    case "picked_up":
      return "default";
    case "transferred":
      return "outline";
    case "returned":
      return "outline";
    case "expired":
      return "destructive";
    case "past_due":
      return "destructive";
    case "missing":
      return "destructive";
    case "rejected":
      return "destructive";
    default:
      return "secondary";
  }
}

function getStateIcon(state: string) {
  switch (state) {
    case "requested":
      return Clock;
    case "approved":
      return Check;
    case "rejected":
      return X;
    case "picked_up":
      return Package;
    case "transferred":
      return PackageCheck;
    case "returned":
      return PackageCheck;
    case "expired":
    case "past_due":
    case "missing":
      return AlertTriangle;
    default:
      return Clock;
  }
}

// Manages a single lease claim with activity and status actions.

