"use client";

import { useQuery } from "convex/react";
import { MessageSquare } from "lucide-react";
import { useTranslations } from "next-intl";
import { useEffect, useState } from "react";

import { Link } from "@/i18n/routing";
import { api } from "@/convex/_generated/api";
import { Button } from "@/components/ui/button";

export function MessagesBell() {
  const t = useTranslations("Messages");
  const unread = useQuery(api.messaging.getMyUnreadCount);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  return (
    <Link href="/messages" aria-label={t("title")}>
      <Button variant="ghost" size="icon" className="relative">
        <MessageSquare className="h-5 w-5" />
        {mounted && (unread ?? 0) > 0 && (
          <span className="absolute top-1 right-1 h-2.5 w-2.5 rounded-full bg-red-500 ring-2 ring-white" />
        )}
        <span className="sr-only">{t("title")}</span>
      </Button>
    </Link>
  );
}

import { v } from "convex/values";
import type { Doc, Id } from "./_generated/dataModel";
import type { MutationCtx, QueryCtx } from "./_generated/server";
import { mutation, query } from "./_generated/server";

const MAX_BODY_LENGTH = 2000;
const PREVIEW_LENGTH = 120;

function sortPair(a: string, b: string): [string, string] {
  return a < b ? [a, b] : [b, a];
}

function makeParticipantsKey(userA: string, userB: string, itemId: string) {
  const [first, second] = sortPair(userA, userB);
  return `${first}|${second}|${itemId}`;
}

function previewFrom(body: string): string {
  const trimmed = body.trim().replace(/\s+/g, " ");
  return trimmed.length <= PREVIEW_LENGTH
    ? trimmed
    : `${trimmed.slice(0, PREVIEW_LENGTH - 1)}…`;
}

async function findConversation(
  ctx: QueryCtx | MutationCtx,
  itemId: Id<"items">,
  userA: string,
  userB: string,
): Promise<Doc<"conversations"> | null> {
  const key = makeParticipantsKey(userA, userB, itemId);
  return await ctx.db
    .query("conversations")
    .withIndex("by_participantsKey", (q) => q.eq("participantsKey", key))
    .first();
}

async function ensureConversation(
  ctx: MutationCtx,
  args: {
    itemId: Id<"items">;
    ownerId: string;
    borrowerId: string;
    claimId?: Id<"claims">;
  },
): Promise<Doc<"conversations">> {
  const existing = await findConversation(
    ctx,
    args.itemId,
    args.ownerId,
    args.borrowerId,
  );
  if (existing) {
    if (args.claimId && !existing.claimId) {
      await ctx.db.patch(existing._id, { claimId: args.claimId });
      const updated = await ctx.db.get(existing._id);
      if (updated) return updated;
    }
    return existing;
  }
  const [first, second] = sortPair(args.ownerId, args.borrowerId);
  const now = Date.now();
  const id = await ctx.db.insert("conversations", {
    itemId: args.itemId,
    claimId: args.claimId,
    participantIds: [first, second],
    participantsKey: makeParticipantsKey(
      args.ownerId,
      args.borrowerId,
      args.itemId,
    ),
    lastMessageAt: now,
    createdAt: now,
  });
  const created = await ctx.db.get(id);
  if (!created) throw new Error("Failed to create conversation");
  return created;
}

/**
 * Internal helper used by claim lifecycle mutations to append a system message
 * into the borrower<->owner conversation. Creates the conversation if needed.
 * Does NOT throw — system messaging is best-effort and must not break the
 * underlying claim mutation.
 */
export async function appendClaimSystemMessage(
  ctx: MutationCtx,
  args: {
    itemId: Id<"items">;
    claimId: Id<"claims">;
    ownerId: string;
    borrowerId: string;
    systemType: string;
    body: string;
  },
): Promise<void> {
  if (args.ownerId === args.borrowerId) return;
  try {
    const conversation = await ensureConversation(ctx, {
      itemId: args.itemId,
      ownerId: args.ownerId,
      borrowerId: args.borrowerId,
      claimId: args.claimId,
    });
    const now = Date.now();
    await ctx.db.insert("conversation_messages", {
      conversationId: conversation._id,
      senderId: "system",
      kind: "system",
      systemType: args.systemType,
      body: args.body,
      createdAt: now,
    });
    await ctx.db.patch(conversation._id, {
      lastMessageAt: now,
      lastMessagePreview: previewFrom(args.body),
    });
  } catch (err) {
    console.warn("[messaging] failed to append system message", err);
  }
}

export const startConversation = mutation({
  args: {
    itemId: v.id("items"),
    claimId: v.optional(v.id("claims")),
  },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Unauthenticated");
    const userId = identity.subject;

    const item = await ctx.db.get(args.itemId);
    if (!item) throw new Error("Item not found");

    let ownerId = item.ownerId;
    let borrowerId = userId;

    if (item.ownerId === userId) {
      // Owner can only open an existing conversation, scoped via claimId.
      if (!args.claimId) {
        throw new Error("Owners cannot start a conversation with themselves");
      }
      const claim = await ctx.db.get(args.claimId);
      if (!claim || claim.itemId !== args.itemId) {
        throw new Error("Claim not found");
      }
      borrowerId = claim.claimerId;
    }

    if (args.claimId) {
      const claim = await ctx.db.get(args.claimId);
      if (!claim || claim.itemId !== args.itemId) {
        throw new Error("Claim not found");
      }
      // Make sure the claim ties to this borrower<->owner pair.
      if (
        claim.claimerId !== borrowerId ||
        item.ownerId !== ownerId
      ) {
        throw new Error("Claim does not match conversation participants");
      }
    }

    const conversation = await ensureConversation(ctx, {
      itemId: args.itemId,
      ownerId,
      borrowerId,
      claimId: args.claimId,
    });
    return conversation._id;
  },
});

export const sendMessage = mutation({
  args: {
    conversationId: v.id("conversations"),
    body: v.string(),
  },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Unauthenticated");
    const userId = identity.subject;

    const body = args.body.trim();
    if (!body) throw new Error("Message body cannot be empty");
    if (body.length > MAX_BODY_LENGTH) {
      throw new Error(`Message too long (max ${MAX_BODY_LENGTH} chars)`);
    }

    const conversation = await ctx.db.get(args.conversationId);
    if (!conversation) throw new Error("Conversation not found");
    if (!conversation.participantIds.includes(userId)) {
      throw new Error("Unauthorized");
    }

    const now = Date.now();
    const messageId = await ctx.db.insert("conversation_messages", {
      conversationId: args.conversationId,
      senderId: userId,
      kind: "text",
      body,
      createdAt: now,
    });
    await ctx.db.patch(args.conversationId, {
      lastMessageAt: now,
      lastMessagePreview: previewFrom(body),
    });

    // Ensure sender is marked read up to the moment they sent.
    await upsertRead(ctx, args.conversationId, userId, now);
    return messageId;
  },
});

async function upsertRead(
  ctx: MutationCtx,
  conversationId: Id<"conversations">,
  userId: string,
  lastReadAt: number,
): Promise<void> {
  const existing = await ctx.db
    .query("conversation_reads")
    .withIndex("by_user_conversation", (q) =>
      q.eq("userId", userId).eq("conversationId", conversationId),
    )
    .first();
  if (existing) {
    if (existing.lastReadAt < lastReadAt) {
      await ctx.db.patch(existing._id, { lastReadAt });
    }
  } else {
    await ctx.db.insert("conversation_reads", {
      conversationId,
      userId,
      lastReadAt,
    });
  }
}

export const markRead = mutation({
  args: {
    conversationId: v.id("conversations"),
  },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Unauthenticated");
    const userId = identity.subject;

    const conversation = await ctx.db.get(args.conversationId);
    if (!conversation) throw new Error("Conversation not found");
    if (!conversation.participantIds.includes(userId)) {
      throw new Error("Unauthorized");
    }

    await upsertRead(ctx, args.conversationId, userId, Date.now());
  },
});

type ConversationSummary = {
  _id: Id<"conversations">;
  itemId: Id<"items">;
  itemName: string;
  itemImageUrl: string | null;
  claimId: Id<"claims"> | null;
  otherUserId: string;
  otherUserName: string | null;
  otherUserAvatarUrl: string | null;
  lastMessageAt: number;
  lastMessagePreview: string | null;
  unreadCount: number;
};

async function summarizeConversation(
  ctx: QueryCtx,
  conversation: Doc<"conversations">,
  userId: string,
): Promise<ConversationSummary | null> {
  const item = await ctx.db.get(conversation.itemId);
  if (!item) return null;

  const otherUserId =
    conversation.participantIds.find((p) => p !== userId) ?? userId;
  const otherProfile = await ctx.db
    .query("users")
    .withIndex("by_clerk_id", (q) => q.eq("clerkId", otherUserId))
    .first();

  const read = await ctx.db
    .query("conversation_reads")
    .withIndex("by_user_conversation", (q) =>
      q.eq("userId", userId).eq("conversationId", conversation._id),
    )
    .first();
  const lastReadAt = read?.lastReadAt ?? 0;

  // Count unread (cap at 99 — prototype scale).
  let unreadCount = 0;
  const messages = await ctx.db
    .query("conversation_messages")
    .withIndex("by_conversation_createdAt", (q) =>
      q.eq("conversationId", conversation._id).gt("createdAt", lastReadAt),
    )
    .take(100);
  for (const m of messages) {
    if (m.senderId !== userId) unreadCount += 1;
    if (unreadCount >= 99) break;
  }

  const cloud = item.imageCloudinary?.[0]?.secureUrl ?? null;

  return {
    _id: conversation._id,
    itemId: conversation.itemId,
    itemName: item.name,
    itemImageUrl: cloud,
    claimId: conversation.claimId ?? null,
    otherUserId,
    otherUserName: otherProfile?.name ?? null,
    otherUserAvatarUrl: otherProfile?.avatarCloudinary?.secureUrl ?? null,
    lastMessageAt: conversation.lastMessageAt,
    lastMessagePreview: conversation.lastMessagePreview ?? null,
    unreadCount,
  };
}

export const listMyConversations = query({
  args: {},
  handler: async (ctx): Promise<ConversationSummary[]> => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) return [];
    const userId = identity.subject;

    // Prototype scale: scan recent conversations and filter by participant.
    const all = await ctx.db.query("conversations").order("desc").take(500);
    const mine = all.filter((c) => c.participantIds.includes(userId));

    const summaries = await Promise.all(
      mine.map((c) => summarizeConversation(ctx, c, userId)),
    );
    return summaries
      .filter((s): s is ConversationSummary => s !== null)
      .sort((a, b) => b.lastMessageAt - a.lastMessageAt);
  },
});

export const getMyUnreadCount = query({
  args: {},
  handler: async (ctx): Promise<number> => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) return 0;
    const userId = identity.subject;

    const all = await ctx.db.query("conversations").order("desc").take(500);
    const mine = all.filter((c) => c.participantIds.includes(userId));

    let total = 0;
    for (const c of mine) {
      const read = await ctx.db
        .query("conversation_reads")
        .withIndex("by_user_conversation", (q) =>
          q.eq("userId", userId).eq("conversationId", c._id),
        )
        .first();
      const lastReadAt = read?.lastReadAt ?? 0;
      if (c.lastMessageAt <= lastReadAt) continue;
      const recent = await ctx.db
        .query("conversation_messages")
        .withIndex("by_conversation_createdAt", (q) =>
          q.eq("conversationId", c._id).gt("createdAt", lastReadAt),
        )
        .take(50);
      for (const m of recent) {
        if (m.senderId !== userId) total += 1;
      }
    }
    return total;
  },
});

export const getConversation = query({
  args: { conversationId: v.id("conversations") },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Unauthenticated");
    const userId = identity.subject;

    const conversation = await ctx.db.get(args.conversationId);
    if (!conversation) return null;
    if (!conversation.participantIds.includes(userId)) {
      throw new Error("Unauthorized");
    }

    const item = await ctx.db.get(conversation.itemId);
    const otherUserId =
      conversation.participantIds.find((p) => p !== userId) ?? userId;
    const otherProfile = await ctx.db
      .query("users")
      .withIndex("by_clerk_id", (q) => q.eq("clerkId", otherUserId))
      .first();

    return {
      _id: conversation._id,
      itemId: conversation.itemId,
      itemName: item?.name ?? "",
      itemImageUrl: item?.imageCloudinary?.[0]?.secureUrl ?? null,
      claimId: conversation.claimId ?? null,
      isOwner: item?.ownerId === userId,
      otherUserId,
      otherUserName: otherProfile?.name ?? null,
      otherUserAvatarUrl: otherProfile?.avatarCloudinary?.secureUrl ?? null,
      participantIds: conversation.participantIds,
    };
  },
});

export const listMessages = query({
  args: {
    conversationId: v.id("conversations"),
    limit: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Unauthenticated");
    const userId = identity.subject;

    const conversation = await ctx.db.get(args.conversationId);
    if (!conversation) throw new Error("Conversation not found");
    if (!conversation.participantIds.includes(userId)) {
      throw new Error("Unauthorized");
    }

    const limit = Math.min(args.limit ?? 200, 500);
    const messages = await ctx.db
      .query("conversation_messages")
      .withIndex("by_conversation_createdAt", (q) =>
        q.eq("conversationId", args.conversationId),
      )
      .order("asc")
      .take(limit);
    return messages;
  },
});
